use vstd::prelude::*;

verus! {

    // Given two arrays of i8's of equal length, produce a boolean array of the same length,
    // indicating at each index whether a[i] < b[i].
    // If empty input, return empty output.
    fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
        // Require that inputs have equal length
        requires(a.len() == b.len());
        // Ensures output length equals input length
        ensures(|result: &Vec<bool>| result.len() == a.len());
        // Ensures for each index, result[i] == (a[i] < b[i])
        ensures(|result: &Vec<bool>| 
            forall(|i: usize| (i < a.len()) ==> (result[i] == (a[i] < b[i])))
        );

        let mut res: Vec<bool> = Vec::new();

        let mut i: usize = 0;
        // Loop invariant to track progress and correctness of partial result
        while i < a.len() {
            invariant(i <= a.len());
            invariant(res.len() == i);
            invariant(forall(|j: usize| (j < i) ==> (res[j] == (a[j] < b[j]))));
            decreases(a.len() - i);

            res.push(a[i] < b[i]);
            i = i + 1;
        }
        res
    }
}